// Classes pages (generated by scripts/build-classes.mjs).
//  - Course pages: an "Open all units" button, and the unit named in the
//    address (#unit-slug) opens by itself.
//  - For a signed-in student: progress per skill, topic and course, from
//    the database function curriculum_progress() (supabase/curriculum.sql).
//    Progress counts questions answered in activities, tagged with the
//    curriculum skills they practise. It never claims mastery.
// Guests see the pages exactly as generated. Text is set as text only.
(function () {
  'use strict';

  // ---------- units ----------
  var units = [].slice.call(document.querySelectorAll('details.cls-unit'));
  var expand = document.querySelector('[data-expand-all]');
  if (expand && units.length) {
    var sync = function () { expand.textContent = units.every(function (u) { return u.open; }) ? 'Close all units' : 'Open all units'; };
    expand.hidden = false;
    expand.addEventListener('click', function () { var open = !units.every(function (u) { return u.open; }); units.forEach(function (u) { u.open = open; }); sync(); });
    units.forEach(function (u) { u.addEventListener('toggle', sync); });
    var openFromHash = function () {
      var id = decodeURIComponent(location.hash.slice(1)), u = id && document.getElementById(id);
      if (u && u.tagName === 'DETAILS') { u.open = true; u.scrollIntoView(); }
      sync();
    };
    window.addEventListener('hashchange', openFromHash);
    openFromHash();
  }

  // ---------- progress ----------
  var A = window.MathleteAuth;
  var plural = function (n, one, many) { return n + ' ' + (n === 1 ? one : (many || one + 's')); };
  var skillsOf = function (el) { return (el.getAttribute('data-skills') || '').split(' ').filter(Boolean); };
  var topicHead = document.querySelector('.cls-head--topic');
  var note = document.querySelector('[data-progress-note]');
  var hasActivities = !!document.querySelector('.cls-activity');

  function guest() {
    if (note && hasActivities) {
      note.textContent = '';
      note.appendChild(document.createTextNode('Log in while you practise and your progress on this topic is saved and shown here. '));
      var a = document.createElement('a'); a.href = 'login.html?next=' + encodeURIComponent(location.pathname.replace(/^\//, '')); a.textContent = 'Log in';
      note.appendChild(a); note.hidden = false;
    }
  }

  function show(data) {
    var skills = data.skills || {}, acts = data.activities || {};
    var practised = function (ids) { return ids.filter(function (id) { return skills[id] && skills[id].questions; }).length; };

    // Topic page: each skill and each activity.
    document.querySelectorAll('[data-skill]').forEach(function (li) {
      var s = skills[li.getAttribute('data-skill')], out = li.querySelector('.cls-skill-status');
      if (!out) return;
      out.textContent = s ? plural(s.questions, 'question') + ', ' + s.first_try + ' right first try' : 'Not practised yet';
      out.hidden = false;
    });
    document.querySelectorAll('[data-activity-status]').forEach(function (p) {
      var a = acts[p.getAttribute('data-activity-status')];
      p.textContent = a ? 'You’ve opened this ' + plural(a.sessions, 'time') + (a.completed ? ' and finished it' + (a.completed > 1 ? ' ' + a.completed + ' times' : '') : '') + '.' : 'You haven’t tried this one yet.';
      p.hidden = false;
    });
    if (topicHead && note) {
      var ids = skillsOf(topicHead), n = practised(ids);
      note.textContent = n ? 'You’ve practised ' + n + ' of ' + plural(ids.length, 'skill') + ' in this topic. This shows practice, not a grade.' : (hasActivities ? 'Your practice on this topic will show here once you try an activity.' : '');
      note.hidden = !note.textContent;
    }

    // Course page: each topic.
    document.querySelectorAll('.cls-topic[data-topic]').forEach(function (li) {
      var ids = skillsOf(li), n = practised(ids), out = li.querySelector('[data-topic-status]');
      if (!out || !n) return;
      out.textContent = '✓ ' + n + ' of ' + ids.length + ' skills practised';
      out.hidden = false;
    });

    // Course cards and course header: topics started.
    document.querySelectorAll('[data-course-progress]').forEach(function (p) {
      var course = p.getAttribute('data-course-progress') + '.';
      var started = {};
      Object.keys(skills).forEach(function (id) { if (id.indexOf(course) === 0 && skills[id].questions) started[id.split('.').slice(0, 2).join('.')] = true; });
      var n = Object.keys(started).length;
      if (!n) return;
      p.textContent = 'You’ve started ' + n + ' of ' + p.getAttribute('data-topics') + ' topics.';
      p.hidden = false;
    });
  }

  function start() {
    if (!A || !A.configured) return;
    if (!A.hasStoredSession()) return guest();
    A.status().then(function (st) {
      if (!st || !st.user || !st.member) return guest();
      return A.client().then(function (sb) {
        // One course's skills on course and topic pages; everything on the landing page.
        var head = document.querySelector('[data-course-progress]');
        var prefix = topicHead ? topicHead.getAttribute('data-topic').split('.')[0] + '.' : (document.querySelectorAll('[data-course-progress]').length === 1 && head ? head.getAttribute('data-course-progress') + '.' : null);
        return sb.rpc('curriculum_progress', { p_prefix: prefix }).then(function (res) {
          if (res.error) { if (window.console) console.warn('[Mathlete] progress not available:', res.error.message); return; }
          show(res.data || {});
        });
      });
    }).catch(function () { /* progress is a bonus: the page works without it */ });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
